-- Walkies rivals: tug of war duels and World Cup knockouts. Safe to run again.
-- Each statement is on one line because the SQL tool used to apply it stalls on multi-line function bodies.
-- Direct table access is closed (RLS on, no policies); everything goes through the functions below.

alter table public.profiles add column if not exists state text check (state in ('NSW','VIC','QLD','WA','SA','TAS','ACT','NT')); alter table public.profiles add column if not exists city text check (char_length(city) <= 40); alter table public.profiles add column if not exists open_to_rivals boolean not null default false; alter table public.profiles add column if not exists rival_code text unique default upper(substr(md5(random()::text || clock_timestamp()::text), 1, 6)); grant update (display_name, buddy_name, state, city, open_to_rivals) on public.profiles to authenticated;

create table if not exists public.duels (id uuid primary key default gen_random_uuid(), kind text not null check (kind in ('person','team','state','city')), a_ref text not null, b_ref text not null, created_by uuid not null references auth.users(id) on delete cascade, status text not null default 'active' check (status in ('pending','active','declined')), days int not null check (days between 1 and 30), starts_on date, ends_on date, is_random boolean not null default false, created_at timestamptz not null default now(), check (a_ref <> b_ref)); alter table public.duels enable row level security; create table if not exists public.tournaments (id uuid primary key default gen_random_uuid(), name text not null check (char_length(name) between 2 and 40), kind text not null check (kind in ('team','state','city')), size int not null check (size in (4,8,16)), round_days int not null default 3 check (round_days between 1 and 14), status text not null default 'open' check (status in ('open','running','finished')), starts_on date, created_by uuid not null references auth.users(id) on delete cascade, created_at timestamptz not null default now()); create table if not exists public.tournament_entries (tournament_id uuid not null references public.tournaments(id) on delete cascade, ref text not null, label text not null, seed int, primary key (tournament_id, ref)); create table if not exists public.tournament_matches (tournament_id uuid not null references public.tournaments(id) on delete cascade, round int not null, slot int not null, a_ref text, b_ref text, a_label text, b_label text, starts_on date not null, ends_on date not null, winner_ref text, primary key (tournament_id, round, slot)); alter table public.tournaments enable row level security; alter table public.tournament_entries enable row level security; alter table public.tournament_matches enable row level security;

create or replace function public.my_ref(p_kind text) returns text language sql stable security definer set search_path = public as $fn$ select case p_kind when 'person' then user_id::text when 'team' then workplace_id::text when 'state' then state when 'city' then nullif(lower(trim(city)), '') end from public.profiles where user_id = auth.uid() $fn$;

create or replace function public.side_label(p_kind text, p_ref text) returns text language sql stable security definer set search_path = public as $fn$ select case p_kind when 'person' then (select display_name from public.profiles where user_id::text = p_ref) when 'team' then (select name from public.workplaces where id::text = p_ref) when 'state' then p_ref else initcap(p_ref) end $fn$;

create or replace function public.side_stats(p_kind text, p_ref text, p_from date, p_to date) returns table (members int, total bigint) language sql stable security definer set search_path = public as $fn$ select count(*)::int, coalesce(sum(x.t), 0)::bigint from (select (select coalesce(sum(s.steps), 0) from public.step_days s where s.user_id = p.user_id and s.day between p_from and p_to) as t from public.profiles p where case p_kind when 'person' then p.user_id::text = p_ref when 'team' then p.workplace_id::text = p_ref when 'state' then p.state = p_ref when 'city' then lower(trim(p.city)) = p_ref else false end) x $fn$;

create or replace function public.duel_options(p_kind text) returns table (ref text, label text, members int) language sql stable security definer set search_path = public as $fn$ select o.ref, o.label, o.members from (select 'team'::text as kind, w.id::text as ref, w.name as label, count(*)::int as members from public.workplaces w join public.profiles p on p.workplace_id = w.id group by w.id, w.name union all select 'state', p.state, p.state, count(*)::int from public.profiles p where p.state is not null group by p.state union all select 'city', lower(trim(p.city)), min(initcap(lower(trim(p.city)))), count(*)::int from public.profiles p where nullif(trim(p.city), '') is not null group by lower(trim(p.city))) o where o.kind = p_kind and o.ref is distinct from public.my_ref(p_kind) order by o.members desc, o.label $fn$;

create or replace function public.create_duel(p_kind text, p_opponent text, p_days int, p_random boolean) returns uuid language plpgsql security definer set search_path = public as $fn$ declare me uuid := auth.uid(); a text; b text; d public.duels; n int := greatest(1, least(coalesce(p_days, 7), 30)); begin if me is null then raise exception 'Sign in first'; end if; if p_kind not in ('person','team','state','city') then raise exception 'Pick who you want to challenge'; end if; a := public.my_ref(p_kind); if a is null then raise exception using message = case p_kind when 'team' then 'Join a team first' when 'state' then 'Set your state in the Me tab first' when 'city' then 'Set your city in the Me tab first' else 'Sign in first' end; end if; if (select count(*) from public.duels du where du.kind = p_kind and du.status in ('pending','active') and (du.ends_on is null or du.ends_on >= current_date) and (du.a_ref = a or du.b_ref = a)) >= 3 then raise exception 'You already have 3 tug of wars going. Wait for one to finish.'; end if; if coalesce(p_random, false) then b := case p_kind when 'person' then (select pr.user_id::text from public.profiles pr where pr.open_to_rivals and pr.user_id <> me order by random() limit 1) when 'team' then (select w.id::text from public.workplaces w where w.id::text <> a and exists (select 1 from public.profiles pr where pr.workplace_id = w.id) order by random() limit 1) when 'state' then (select pr.state from public.profiles pr where pr.state is not null and pr.state <> a group by pr.state order by random() limit 1) else (select lower(trim(pr.city)) from public.profiles pr where nullif(trim(pr.city), '') is not null and lower(trim(pr.city)) <> a group by lower(trim(pr.city)) order by random() limit 1) end; else b := case p_kind when 'person' then (select pr.user_id::text from public.profiles pr where pr.rival_code = upper(trim(p_opponent))) when 'team' then (select w.id::text from public.workplaces w where w.id::text = trim(p_opponent)) when 'state' then (select pr.state from public.profiles pr where pr.state = upper(trim(p_opponent)) limit 1) else (select lower(trim(pr.city)) from public.profiles pr where lower(trim(pr.city)) = lower(trim(p_opponent)) limit 1) end; end if; if b is null then raise exception using message = case when coalesce(p_random, false) then 'No one is available to challenge yet. Try again soon.' else 'We could not find that rival' end; end if; if b = a then raise exception 'You cannot challenge yourself'; end if; insert into public.duels (kind, a_ref, b_ref, created_by, status, days, starts_on, ends_on, is_random) values (p_kind, a, b, me, case when p_kind = 'person' then 'pending' else 'active' end, n, case when p_kind = 'person' then null else current_date end, case when p_kind = 'person' then null else current_date + n - 1 end, coalesce(p_random, false)) returning * into d; return d.id; end $fn$;

create or replace function public.respond_duel(p_id uuid, p_accept boolean) returns void language plpgsql security definer set search_path = public as $fn$ declare d public.duels; begin select * into d from public.duels where id = p_id and kind = 'person' and b_ref = auth.uid()::text and status = 'pending'; if not found then raise exception 'That challenge is no longer available'; end if; if p_accept then update public.duels set status = 'active', starts_on = current_date, ends_on = current_date + d.days - 1 where id = p_id; else update public.duels set status = 'declined' where id = p_id; end if; end $fn$;

create or replace function public.my_duels() returns table (id uuid, kind text, status text, incoming boolean, my_label text, rival_label text, my_members int, rival_members int, my_total bigint, rival_total bigint, starts_on date, ends_on date, days_left int, finished boolean, is_random boolean) language sql stable security definer set search_path = public as $fn$ with d as (select du.*, ((du.kind = 'person' and du.b_ref = auth.uid()::text) or (du.kind <> 'person' and du.b_ref = public.my_ref(du.kind))) as i_am_b from public.duels du where du.status <> 'declined' and (du.ends_on is null or du.ends_on >= current_date - 2) and (du.created_by = auth.uid() or (du.kind = 'person' and (du.a_ref = auth.uid()::text or du.b_ref = auth.uid()::text)) or (du.kind <> 'person' and (du.a_ref = public.my_ref(du.kind) or du.b_ref = public.my_ref(du.kind))))) select d.id, d.kind, d.status, (d.status = 'pending' and d.i_am_b), public.side_label(d.kind, case when d.i_am_b then d.b_ref else d.a_ref end), public.side_label(d.kind, case when d.i_am_b then d.a_ref else d.b_ref end), ms.members, rs.members, ms.total, rs.total, d.starts_on, d.ends_on, case when d.ends_on is null then d.days else greatest(0, d.ends_on - current_date + 1) end, (d.ends_on is not null and d.ends_on < current_date), d.is_random from d cross join lateral public.side_stats(d.kind, case when d.i_am_b then d.b_ref else d.a_ref end, coalesce(d.starts_on, current_date + 1), coalesce(d.ends_on, current_date)) ms cross join lateral public.side_stats(d.kind, case when d.i_am_b then d.a_ref else d.b_ref end, coalesce(d.starts_on, current_date + 1), coalesce(d.ends_on, current_date)) rs order by (d.status = 'pending' and d.i_am_b) desc, d.ends_on desc nulls first $fn$;

create or replace function public.advance_tournament(p_id uuid) returns void language plpgsql security definer set search_path = public as $fn$ declare t public.tournaments; m record; sa record; sb record; w text; i int; begin select * into t from public.tournaments where tournaments.id = p_id; if not found or t.status = 'open' then return; end if; for i in 1..5 loop for m in select * from public.tournament_matches tm where tm.tournament_id = p_id and tm.winner_ref is null and tm.a_ref is not null and ((tm.round = 1 and tm.b_ref is null) or (tm.b_ref is not null and tm.ends_on < current_date)) loop if m.b_ref is null then w := m.a_ref; else select * into sa from public.side_stats(t.kind, m.a_ref, m.starts_on, m.ends_on); select * into sb from public.side_stats(t.kind, m.b_ref, m.starts_on, m.ends_on); w := case when coalesce(sa.total::numeric / nullif(sa.members, 0), 0) >= coalesce(sb.total::numeric / nullif(sb.members, 0), 0) then m.a_ref else m.b_ref end; end if; update public.tournament_matches set winner_ref = w where tournament_id = p_id and round = m.round and slot = m.slot; end loop; update public.tournament_matches nx set a_ref = x.w, a_label = x.l from (select f.round + 1 as r, f.slot / 2 as s, f.winner_ref as w, case when f.winner_ref = f.a_ref then f.a_label else f.b_label end as l from public.tournament_matches f where f.tournament_id = p_id and f.winner_ref is not null and f.slot % 2 = 0) x where nx.tournament_id = p_id and nx.round = x.r and nx.slot = x.s and nx.a_ref is null; update public.tournament_matches nx set b_ref = x.w, b_label = x.l from (select f.round + 1 as r, f.slot / 2 as s, f.winner_ref as w, case when f.winner_ref = f.a_ref then f.a_label else f.b_label end as l from public.tournament_matches f where f.tournament_id = p_id and f.winner_ref is not null and f.slot % 2 = 1) x where nx.tournament_id = p_id and nx.round = x.r and nx.slot = x.s and nx.b_ref is null; end loop; update public.tournaments set status = 'finished' where id = p_id and exists (select 1 from public.tournament_matches f where f.tournament_id = p_id and f.round = (select max(g.round) from public.tournament_matches g where g.tournament_id = p_id) and f.winner_ref is not null); end $fn$;

create or replace function public.start_tournament(p_id uuid) returns void language plpgsql security definer set search_path = public as $fn$ declare t public.tournaments; n int; sz int := 2; rounds int := 1; r int; s int; begin select * into t from public.tournaments where tournaments.id = p_id for update; if t.status <> 'open' then return; end if; select count(*) into n from public.tournament_entries where tournament_id = p_id; if n < 2 then raise exception 'You need at least 2 sides to kick off'; end if; while sz < n loop sz := sz * 2; rounds := rounds + 1; end loop; update public.tournaments set status = 'running', starts_on = current_date where id = p_id; update public.tournament_entries e set seed = sh.rn from (select ref, row_number() over (order by random()) as rn from public.tournament_entries where tournament_id = p_id) sh where e.tournament_id = p_id and e.ref = sh.ref; for r in 1..rounds loop for s in 0..((sz >> r) - 1) loop insert into public.tournament_matches (tournament_id, round, slot, a_ref, b_ref, a_label, b_label, starts_on, ends_on) values (p_id, r, s, (select e.ref from public.tournament_entries e where e.tournament_id = p_id and r = 1 and e.seed = s + 1), (select e.ref from public.tournament_entries e where e.tournament_id = p_id and r = 1 and e.seed = s + 1 + (sz >> 1)), (select e.label from public.tournament_entries e where e.tournament_id = p_id and r = 1 and e.seed = s + 1), (select e.label from public.tournament_entries e where e.tournament_id = p_id and r = 1 and e.seed = s + 1 + (sz >> 1)), current_date + (r - 1) * t.round_days, current_date + r * t.round_days - 1); end loop; end loop; perform public.advance_tournament(p_id); end $fn$;

create or replace function public.create_tournament(p_name text, p_kind text, p_size int, p_round_days int) returns uuid language plpgsql security definer set search_path = public as $fn$ declare me uuid := auth.uid(); r text; t public.tournaments; begin if me is null then raise exception 'Sign in first'; end if; if p_kind not in ('team','state','city') then raise exception 'Pick teams, states or cities'; end if; r := public.my_ref(p_kind); if r is null then raise exception using message = case p_kind when 'team' then 'Join a team first' when 'state' then 'Set your state in the Me tab first' else 'Set your city in the Me tab first' end; end if; if (select count(*) from public.tournaments x where x.created_by = me and x.status <> 'finished') >= 3 then raise exception 'You already have 3 World Cups going'; end if; if char_length(trim(coalesce(p_name, ''))) < 2 then raise exception 'Give your World Cup a name'; end if; insert into public.tournaments (name, kind, size, round_days, created_by) values (left(trim(p_name), 40), p_kind, p_size, coalesce(p_round_days, 3), me) returning * into t; insert into public.tournament_entries (tournament_id, ref, label) values (t.id, r, public.side_label(p_kind, r)); return t.id; end $fn$;

create or replace function public.join_tournament(p_id uuid) returns void language plpgsql security definer set search_path = public as $fn$ declare t public.tournaments; r text; n int; begin select * into t from public.tournaments where tournaments.id = p_id; if not found then raise exception 'We could not find that World Cup'; end if; if t.status <> 'open' then raise exception 'That World Cup has already kicked off'; end if; r := public.my_ref(t.kind); if r is null then raise exception using message = case t.kind when 'team' then 'Join a team first' when 'state' then 'Set your state in the Me tab first' else 'Set your city in the Me tab first' end; end if; if exists (select 1 from public.tournament_entries e where e.tournament_id = p_id and e.ref = r) then raise exception 'You are already in this World Cup'; end if; select count(*) into n from public.tournament_entries where tournament_id = p_id; if n >= t.size then raise exception 'This World Cup is full'; end if; insert into public.tournament_entries (tournament_id, ref, label) values (p_id, r, public.side_label(t.kind, r)); if n + 1 >= t.size then perform public.start_tournament(p_id); end if; end $fn$;

create or replace function public.start_tournament_now(p_id uuid) returns void language plpgsql security definer set search_path = public as $fn$ begin if not exists (select 1 from public.tournaments t where t.id = p_id and t.created_by = auth.uid()) then raise exception 'Only the person who created this World Cup can kick it off'; end if; perform public.start_tournament(p_id); end $fn$;

create or replace function public.list_tournaments() returns table (id uuid, name text, kind text, size int, round_days int, status text, entries int, i_am_in boolean, is_mine boolean, champion text) language plpgsql security definer set search_path = public as $fn$ declare x record; begin for x in select tt.id from public.tournaments tt where tt.status = 'running' loop perform public.advance_tournament(x.id); end loop; return query select t.id, t.name, t.kind, t.size, t.round_days, t.status, (select count(*)::int from public.tournament_entries e where e.tournament_id = t.id), exists (select 1 from public.tournament_entries e where e.tournament_id = t.id and e.ref = public.my_ref(t.kind)), t.created_by = auth.uid(), (select case when m.winner_ref = m.a_ref then m.a_label else m.b_label end from public.tournament_matches m where m.tournament_id = t.id and m.round = (select max(mm.round) from public.tournament_matches mm where mm.tournament_id = t.id) and m.winner_ref is not null limit 1) from public.tournaments t where t.status <> 'finished' or t.starts_on >= current_date - 14 order by (t.status = 'open') desc, t.created_at desc limit 20; end $fn$;

create or replace function public.tournament_view(p_id uuid) returns table (rnd int, slot int, a_label text, b_label text, a_ref text, b_ref text, a_avg bigint, b_avg bigint, starts_on date, ends_on date, winner_ref text) language plpgsql security definer set search_path = public as $fn$ declare t public.tournaments; begin select * into t from public.tournaments where tournaments.id = p_id; if not found then return; end if; perform public.advance_tournament(p_id); return query select m.round, m.slot, m.a_label, m.b_label, m.a_ref, m.b_ref, case when m.a_ref is null or m.starts_on > current_date then 0::bigint else (select (s.total / greatest(s.members, 1))::bigint from public.side_stats(t.kind, m.a_ref, m.starts_on, m.ends_on) s) end, case when m.b_ref is null or m.starts_on > current_date then 0::bigint else (select (s.total / greatest(s.members, 1))::bigint from public.side_stats(t.kind, m.b_ref, m.starts_on, m.ends_on) s) end, m.starts_on, m.ends_on, m.winner_ref from public.tournament_matches m where m.tournament_id = p_id order by m.round, m.slot; end $fn$;

create or replace function public.tournament_info(p_id uuid) returns table (name text, kind text, size int, round_days int, status text, is_mine boolean, my_ref text, entries text[]) language sql stable security definer set search_path = public as $fn$ select t.name, t.kind, t.size, t.round_days, t.status, t.created_by = auth.uid(), public.my_ref(t.kind), array(select e.label from public.tournament_entries e where e.tournament_id = t.id order by e.label) from public.tournaments t where t.id = p_id $fn$;

revoke execute on function public.my_ref(text), public.side_label(text, text), public.side_stats(text, text, date, date), public.advance_tournament(uuid), public.start_tournament(uuid) from public, anon, authenticated; revoke execute on function public.duel_options(text), public.create_duel(text, text, int, boolean), public.respond_duel(uuid, boolean), public.my_duels(), public.create_tournament(text, text, int, int), public.join_tournament(uuid), public.start_tournament_now(uuid), public.list_tournaments(), public.tournament_view(uuid), public.tournament_info(uuid) from public, anon; grant execute on function public.duel_options(text), public.create_duel(text, text, int, boolean), public.respond_duel(uuid, boolean), public.my_duels(), public.create_tournament(text, text, int, int), public.join_tournament(uuid), public.start_tournament_now(uuid), public.list_tournaments(), public.tournament_view(uuid), public.tournament_info(uuid) to authenticated;
